pragma solidity 0.8.20;

import { IERC20 } from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import { IBlastKandel } from './mangrove/interfaces/IBlastKandel.sol';
import { IMGV } from './mangrove/interfaces/IMGV.sol';
import { IRangeProtocolMangroveVault } from './interfaces/IRangeProtocolMangroveVault.sol';

/**
 * @notice abstract contract to contain the storage layout of Mangrove vault.
 */
abstract contract RangeProtocolMangroveVaultStorage is IRangeProtocolMangroveVault {
    address _factory; // address of the RangeMangrove factory.
    IBlastKandel _kandel; // vault's Kandel instance.
    IMGV _MGV; // reference to Mangrove contract.
    IERC20 _token0; // vault's token0/base token.
    IERC20 _token1; // vault's token1/quote token.
    bool _inPosition; // status of vault's position on Kandel.
    Position _position; // the vault's position data.
    uint256 _managingFee; // managing fee percentage.
    uint256 _managerBalance0; // manager's balance in token0.
    uint256 _managerBalance1; // manager's balance in token1.
    mapping(address => UserVault) _userVaults; // users vaults mapping to track the initial deposits of users and later the exposure of the user.
    address[] _users; // list of users.

    function factory() external view override returns (address) {
        return _factory;
    }

    function kandel() external view override returns (IBlastKandel) {
        return _kandel;
    }

    function MGV() external view override returns (IMGV) {
        return _MGV;
    }

    function token0() external view override returns (IERC20) {
        return _token0;
    }

    function token1() external view override returns (IERC20) {
        return _token1;
    }

    function inPosition() external view override returns (bool) {
        return _inPosition;
    }

    function position() external view override returns (Position memory) {
        return _position;
    }

    function managingFee() external view override returns (uint256) {
        return _managingFee;
    }

    function managerBalance0() external view override returns (uint256) {
        return _managerBalance0;
    }

    function managerBalance1() external view override returns (uint256) {
        return _managerBalance1;
    }

    function userVaults(address who) external view override returns (UserVault memory) {
        return _userVaults[who];
    }

    function users(uint256 idx) external view override returns (address) {
        return _users[idx];
    }

    function userCount() external view override returns (uint256) {
        return _users.length;
    }
}

