pragma solidity 0.8.20;

import { IERC20 } from 'openzeppelin-contracts/contracts/token/ERC20/IERC20.sol';
import { IBlastKandel } from '../mangrove/interfaces/IBlastKandel.sol';
import { IMGV } from '../mangrove/interfaces/IMGV.sol';
import { Tick } from '../mangrove/libraries/TickLib.sol';

interface IRangeProtocolMangroveVault is IERC20 {
    struct Position {
        uint32 gasprice;
        uint24 gasreq;
        uint32 stepSize;
        uint32 pricePoints;
        uint256 baseQuoteTickOffset;
        uint256 firstAskIndex;
        Tick midTick;
    }

    struct UserVault {
        address user;
        uint256 token0;
        uint256 token1;
